/* CareerRadar Pro — connected PWA. No sample vacancies are shown as genuine jobs. */
'use strict';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={token:sessionStorage.getItem('cr_token')||'',user:null,route:'discover',q:'',location:'',page:1,sort:'recent',jobs:[],total:0,pages:0,saved:[],alerts:[],applications:[],notifications:[],profile:null,activeJob:null,authMode:'login',compare:JSON.parse(localStorage.getItem('cr_compare')||'[]')};
const NAV=[['discover','⌕','Discover'],['saved','♡','Saved jobs'],['alerts','♧','Job alerts'],['applications','▤','Applications'],['resume','▣','My resume'],['tailored','✎','Tailored documents'],['profile','♙','My profile'],['walkins','⌖','Walk-in interviews'],['compare','⇄','Job comparison'],['tools','✦','Career tools'],['insights','▥','My insights']];
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='toast',3800)}
async function api(path,opts={}){const hdr={...(opts.headers||{})};if(S.token)hdr.Authorization='Bearer '+S.token;if(opts.body&&!(opts.body instanceof FormData))hdr['Content-Type']='application/json';let r;try{r=await fetch('/api'+path,{...opts,headers:hdr,body:opts.body&&!(opts.body instanceof FormData)&&typeof opts.body!=='string'?JSON.stringify(opts.body):opts.body})}catch(e){throw Error('Cannot connect to server. Check your connection.')}let j;const ct=r.headers.get('content-type')||'';if(ct.includes('json')){try{j=await r.json()}catch{j={}}}if(!r.ok){if(r.status===401&&S.token){S.token='';S.user=null;sessionStorage.removeItem('cr_token');}throw Error(typeof j?.detail==='string'?j.detail:`Server returned ${r.status}`)}return j}
function date(s){if(!s)return 'Not provided';const d=new Date(s);return Number.isNaN(d.getTime())?'Not provided':d.toLocaleDateString('en-AE',{month:'short',day:'numeric',year:'numeric'})}
function ago(s){if(!s)return 'Date not provided';const d=new Date(s);if(Number.isNaN(d.getTime()))return 'Date unknown';const days=Math.max(0,Math.floor((Date.now()-d)/86400000));return days===0?'Today':days===1?'Yesterday':days<30?`${days} days ago`:date(s)}
function initials(str){return String(str||'CR').trim().slice(0,1).toUpperCase()}
function heading(eyebrow,title,desc,action=''){return `<div class="heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${action}</div>`}
function empty(icon,title,desc,action=''){return `<div class="empty"><div class="empty-icon">${icon}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${extra}></div>`}
function textfield(label,name,value='',rows=4){return `<div class="field full"><label for="f-${esc(name)}">${esc(label)}</label><textarea id="f-${esc(name)}" name="${esc(name)}" rows="${rows}">${esc(value)}</textarea></div>`}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function modal(html){$('#dialog-root').innerHTML=`<div class="dialog-shade" id="shade"><div class="dialog" role="dialog" aria-modal="true">${html}<div style="text-align:right;margin-top:15px"><button class="btn btn-outline btn-small" data-action="close-modal">Close</button></div></div></div>`;$('#shade').addEventListener('click',e=>{if(e.target.id==='shade')closeModal()})}
function closeModal(){$('#dialog-root').innerHTML=''}
async function loadUser(){if(!S.token)return;try{S.user=await api('/auth/me');const [p,s,a,ap,n]=await Promise.all([api('/profile'),api('/saved'),api('/alerts'),api('/applications'),api('/notifications')]);S.profile=p;S.saved=s;S.alerts=a;S.applications=ap;S.notifications=n}catch(e){toast(e.message,true)}}
function refreshNav(){let r=S.route;$('#sidebar-nav').innerHTML=NAV.map(([id,icon,label])=>`<button class="nav-item ${r===id?'active':''}" data-action="${id}"><span class="nav-icon">${icon}</span>${label}${id==='saved'&&S.saved.length?`<span class="nav-count">${S.saved.length}</span>`:''}</button>`).join('')+(S.user?.role==='admin'?`<button class="nav-item ${r==='admin'?'active':''}" data-action="admin"><span class="nav-icon">⚙</span>Admin console</button>`:'');$('#mobile-nav').innerHTML=[NAV[0],NAV[1],NAV[2],NAV[3],NAV.find(x=>x[0]==='tools')].map(([id,icon,label])=>`<button class="nav-item ${r===id?'active':''}" data-action="${id}"><span class="nav-icon">${icon}</span>${label==='Saved jobs'?'Saved':label==='Job alerts'?'Alerts':label==='Applications'?'Tracker':label==='My profile'?'Profile':label}</button>`).join('');$('#breadcrumb').textContent={discover:'Discover jobs',saved:'Saved jobs',alerts:'Job alerts',applications:'Applications',resume:'Resume center',tailored:'Tailored documents',profile:'My profile',notifications:'Notifications',admin:'Admin console',account:'Account settings',job:'Job details'}[r]||'CareerRadar Pro';$('#user-display').textContent=S.user?(S.profile?.full_name||S.user.email.split('@')[0]):'Guest';$('#avatar').textContent=initials(S.profile?.full_name||S.user?.email||'G');$('#notification-dot').hidden=!S.notifications.some(x=>!x.read_at)}
async function navigate(route,params=null){S.route=route;window.location.hash=route;refreshNav();window.scrollTo({top:0,behavior:'instant'});$('#page').innerHTML='<div class="loading-view">Loading...</div>';try{if(!S.user&&route!=='discover'&&route!=='job'){return auth('login')}if(route==='discover')return await discover();if(route==='job')return await jobDetails(params||S.activeJob);if(route==='saved')return await saved();if(route==='alerts')return await alerts();if(route==='applications')return await applications();if(route==='resume')return await resume();if(route==='tailored')return await tailoredPage();if(route==='profile')return await profile();if(route==='notifications')return await notifications();if(route==='account')return await account();if(route==='admin')return await admin();if(route==='walkins')return await walkins();if(route==='compare')return await comparePage();if(route==='tools')return await toolsPage();if(route==='insights')return await insightsPage();return discover()}catch(e){$('#page').innerHTML=empty('⚠','Unable to load',e.message,`<button class="btn" data-action="${esc(route)}">Try again</button>`);toast(e.message,true)}}
function auth(mode='login'){S.authMode=mode;S.route='auth';refreshNav();const register=mode==='register';$('#page').innerHTML=`<div class="signin-wrap"><div class="panel"><div class="signin-header"><img src="/assets/icon.svg" alt="CareerRadar logo"><h1>${register?'Create your account':'Welcome back'}</h1><p>${register?'Join and organize your next career move':'Sign in to save jobs, set alerts and track applications'}</p></div><form id="auth-form">${field('Email address','email','','email','required autocomplete="email"')}${field('Password (at least 10 characters)','password','','password',`required minlength="10" autocomplete="${register?'new-password':'current-password'}"`)}<button class="btn" type="submit">${register?'Create free account':'Sign in'} →</button></form><div class="signin-foot">${register?'Already have an account?':'New to CareerRadar?'} <button data-action="${register?'login':'register'}">${register?'Sign in':'Create account'}</button></div></div><p class="small muted" style="text-align:center">Your data stays in your own account. No paid plan required to explore jobs.</p></div>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const body=formData(e.target);const r=await api('/auth/'+(register?'register':'login'),{method:'POST',body});S.token=r.token;sessionStorage.setItem('cr_token',S.token);S.user=r.user;await loadUser();toast(register?'Account created':'Signed in successfully');navigate(register?'profile':'discover')}catch(err){toast(err.message,true)}finally{button.disabled=false}}}
async function loadJobs(){let r=await api('/jobs?'+new URLSearchParams({q:S.q,location:S.location,page:S.page,sort:S.sort}));S.jobs=r.items;S.total=r.total;S.pages=r.pages}
function jobCard(j){const isSaved=S.saved.some(x=>x.id===j.id);return `<article class="jobcard"><div class="company-logo">${esc(initials(j.company))}</div><div><div class="jobtitle">${esc(j.title)}</div><div class="company">${esc(j.company)}</div><div class="meta-row"><span>⌖ ${esc(j.location||'Location not specified')}</span><span>◷ ${esc(ago(j.posted_at||j.first_seen_at))}</span></div><div class="tags"><span class="tag source">${esc(j.source)}</span><span class="tag">${esc(j.work_type||'Not specified')}</span></div></div><div class="card-actions"><button class="bookmark ${isSaved?'saved':''}" aria-label="${isSaved?'Remove saved job':'Save job'}" data-action="toggle-save" data-id="${esc(j.id)}">${isSaved?'♥':'♡'}</button><button class="btn btn-outline btn-small" data-action="compare-toggle" data-id="${esc(j.id)}">${S.compare.includes(j.id)?'✓ Compare':'+ Compare'}</button><button class="btn btn-small" data-action="view-job" data-id="${esc(j.id)}">Details ↗</button></div></article>`}
async function discover(){await loadJobs();const logged=Boolean(S.user);$('#page').innerHTML=`${heading('JOB DISCOVERY','Discover your next opportunity','Search real vacancies from your configured job sources.',logged?`<button class="btn btn-outline" data-action="alerts">♧ Create job alert</button>`:`<button class="btn" data-action="login">Sign in / Register</button>`)}
 <div class="hero"><div style="position:relative;z-index:1"><div style="font-size:11px;letter-spacing:1.3px;color:#e3ebff;font-weight:800">YOUR CAREER. YOUR NEXT CHAPTER.</div><h2>Great opportunities start with a better search.</h2><p>Find relevant openings, save the ones you love and stay organized throughout your job search.</p><button class="btn" data-action="${logged?'profile':'register'}">${logged?'Personalize my profile':'Get started for free'} →</button></div><div class="hero-icon">◎</div></div>
 <div class="stats"><div class="stat"><div class="stat-ico">▤</div><div><strong>${S.total}</strong><small>Matching jobs</small></div></div><div class="stat"><div class="stat-ico green">♡</div><div><strong>${S.saved.length}</strong><small>Saved jobs</small></div></div><div class="stat"><div class="stat-ico purple">♧</div><div><strong>${S.alerts.length}</strong><small>Job alerts</small></div></div><div class="stat"><div class="stat-ico orange">↗</div><div><strong>${S.applications.length}</strong><small>Applications tracked</small></div></div></div>
 <div class="searchbar"><span style="font-size:22px;color:#7e93bc">⌕</span><input id="search-q" aria-label="Job title or keyword" placeholder="Job title, skills or company..." value="${esc(S.q)}"><input class="location-input" id="search-location" aria-label="City or country" placeholder="⌖ Location, e.g. Dubai" value="${esc(S.location)}"><button class="btn" data-action="search">Search jobs →</button></div>
 <div class="filter-line"><button class="filter-chip" data-action="walkins">⌖ Walk-in interviews</button><button class="filter-chip" data-action="compare">⇄ Compare selected (${S.compare.length})</button><button class="filter-chip" data-action="tools">✦ Career tools</button><button class="filter-chip" data-query="Planning Engineer">Planning Engineer</button><button class="filter-chip" data-query="MEP Engineer">MEP Engineer</button><button class="filter-chip" data-query="Software Developer">Software Developer</button><button class="filter-chip" data-query="Project Manager">Project Manager</button><button class="filter-chip" data-query="" >All jobs</button></div>
 <div class="section-head"><div><h2>Available opportunities</h2><p>${S.total} result${S.total===1?'':'s'} from connected sources</p></div><select id="sort-select" style="border:1px solid #e2e8f3;border-radius:9px;padding:9px;color:#657893"><option value="recent" ${S.sort==='recent'?'selected':''}>Newest first</option><option value="company" ${S.sort==='company'?'selected':''}>Company A–Z</option><option value="title" ${S.sort==='title'?'selected':''}>Job title A–Z</option></select></div>
 <div class="grid-main"><div><div class="joblist">${S.jobs.length?S.jobs.map(jobCard).join(''):empty('⌕',S.q?'No matching vacancies found':'No live jobs connected yet',S.q?'Try a broader search or a different location.':'This workspace starts with no fabricated listings. An administrator can connect approved Greenhouse/Lever feeds or add direct vacancies.',S.q?`<button class="btn btn-outline" data-action="clear-search">Clear filters</button>`:logged&&S.user.role==='admin'?`<button class="btn" data-action="admin">Configure job sources</button>`:`<button class="btn btn-outline" data-action="alerts">Create an alert</button>`)}</div>${S.pages>1?`<div class="pagination"><button class="btn btn-outline btn-small" data-action="prev-page" ${S.page<=1?'disabled':''}>← Previous</button><span class="muted small">Page ${S.page} of ${S.pages}</span><button class="btn btn-outline btn-small" data-action="next-page" ${S.page>=S.pages?'disabled':''}>Next →</button></div>`:''}</div><aside class="right-column"><div class="side-card"><div class="eyebrow">GROW WITH CONFIDENCE</div><h3>Make your profile work for you</h3><p>Relevant job recommendations start with your skills and career preferences.</p><div class="progress"><span style="width:${S.profile?Math.min(100,[S.profile.full_name,S.profile.headline,S.profile.skills,S.profile.desired_titles,S.profile.summary].filter(Boolean).length*20):0}%"></span></div><button class="btn btn-outline btn-small" data-action="${logged?'profile':'register'}">Update profile ↗</button></div><div class="side-card"><h3>✨ Built around your search</h3><p>Save interesting jobs, set keyword alerts, and track every application from one workspace.</p><div class="checkline"><b>✓</b> Private application tracker</div><div class="checkline"><b>✓</b> Repeat-free in-app alerts</div><div class="checkline"><b>✓</b> Source-labelled job listings</div></div></aside></div>`;
 $('#search-q').addEventListener('keydown',e=>{if(e.key==='Enter')performSearch()});$('#search-location').addEventListener('keydown',e=>{if(e.key==='Enter')performSearch()});$('#sort-select').onchange=e=>{S.sort=e.target.value;S.page=1;discover()};document.querySelectorAll('[data-query]').forEach(e=>e.onclick=()=>{S.q=e.dataset.query;S.page=1;discover()})}
function performSearch(){S.q=$('#search-q')?.value?.trim()||'';S.location=$('#search-location')?.value?.trim()||'';S.page=1;discover()}
async function jobDetails(id){if(!id){navigate('discover');return}S.activeJob=id;const j=await api('/jobs/'+encodeURIComponent(id));const [trust,activity]=await Promise.all([api('/jobs/'+encodeURIComponent(id)+'/trust'),api('/jobs/'+encodeURIComponent(id)+'/activity')]);$('#page').innerHTML=`<button class="backlink" data-action="discover">← Back to jobs</button><div class="panel"><div class="detail-header"><div class="company-logo">${esc(initials(j.company))}</div><div><h1>${esc(j.title)}</h1><div class="company">${esc(j.company)} · ${esc(j.location||'Location not specified')}</div></div></div><div class="tags"><span class="tag source">Source: ${esc(j.source)}</span><span class="tag">First seen ${esc(date(j.first_seen_at))}</span><span class="tag">${esc(trust.freshness.replaceAll('_',' '))}</span>${j.posted_at?`<span class="tag">Source updated ${esc(date(j.posted_at))}</span>`:''}</div><div class="detail-sticky"><a class="btn" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">Apply on source ↗</a><button class="btn btn-outline" data-action="toggle-save" data-id="${esc(j.id)}">♡ Save job</button><button class="btn btn-outline" data-action="track-job" data-id="${esc(j.id)}">+ Track application</button><button class="btn btn-outline" data-action="match-job" data-id="${esc(j.id)}">✦ Estimate match</button><button class="btn btn-outline" data-action="compare-toggle" data-id="${esc(j.id)}">⇄ Compare</button><button class="btn btn-outline" data-action="tailor-job" data-id="${esc(j.id)}">✎ Tailor CV + Letter</button><button class="btn btn-outline" data-action="roadmap" data-id="${esc(j.id)}">⌁ Skills roadmap</button><button class="btn btn-outline" data-action="share-whatsapp" data-id="${esc(j.id)}">WhatsApp share</button><button class="btn btn-outline" data-action="directions" data-id="${esc(j.id)}">⌖ Directions</button></div></div><div class="panel"><div class="panel-title"><h2>Job details</h2></div><p class="detail-body">${esc(j.description||'This provider did not publish a detailed description. Open the source to view the vacancy.')}</p><div class="setup-card"><strong>Job authenticity / activity</strong><p>Source: ${esc(trust.source_type)} · Last observed ${esc(date(trust.last_seen_at))} · First discovered ${esc(date(activity.first_discovered))}</p><p>Employer verified: No · Link independently checked: No · Recruiter response rate: Not available</p><p>${esc(trust.notice)}</p></div><div class="infobar">Source listings may change. Confirm salary, eligibility, and application instructions on the original employer page.</div></div><button class="text-btn" data-action="report-job" data-id="${esc(j.id)}">Report an issue with this vacancy</button>`}
async function saved(){S.saved=await api('/saved');$('#page').innerHTML=heading('YOUR SHORTLIST','Saved jobs','Keep your favorite vacancies organized.',`<button class="btn btn-outline" data-action="discover">Explore opportunities</button>`)+(S.saved.length?`<div class="joblist">${S.saved.map(jobCard).join('')}</div>`:empty('♡','No saved jobs yet','Use the heart icon on any vacancy to save it here.',`<button class="btn" data-action="discover">Find jobs</button>`));refreshNav()}
async function alerts(){S.alerts=await api('/alerts');$('#page').innerHTML=heading('JOB NOTIFICATIONS','Smart job alerts','Stay on top of newly collected matching vacancies.',`<button class="btn" data-action="new-alert">+ Create alert</button>`)+`<div class="panel"><div class="panel-title"><h2>Your alert rules</h2><span class="muted small">${S.alerts.length} alerts</span></div>${S.alerts.length?S.alerts.map(a=>`<div class="row-item"><div><strong>${esc(a.name)}</strong><p>Search: ${esc(a.query||'Any')} · Location: ${esc(a.location||'Anywhere')} · ${esc(a.frequency)}</p></div><button class="btn btn-outline btn-small" data-action="delete-alert" data-id="${esc(a.id)}">Delete</button></div>`).join(''):empty('♧','Get the right jobs at the right time','Create your first alert and the server-side worker will notify you in this workspace when new matches are found.',`<button class="btn" data-action="new-alert">Create my first alert</button>`)}</div><div class="notice">In-app notification delivery requires the background worker to be running. Mobile push and email sending are not enabled in this build.</div>`;refreshNav()}
function newAlert(){modal(`<h2>Create a job alert</h2><p>We'll search newly ingested job records for your keyword and location.</p><form id="alert-form" class="form-grid">${field('Alert name','name','My job alert','text','required')}${field('Search keyword','query',S.q)}${field('City or country','location',S.location)}<div class="field"><label for="f-frequency">Notification frequency</label><select name="frequency" id="f-frequency"><option value="immediate">Immediately (when worker runs)</option><option value="2h">Every 2 hours*</option><option value="6h">Every 6 hours*</option><option value="daily" selected>Daily*</option><option value="weekly">Weekly*</option><option value="off">Off</option></select></div><div class="field full"><small class="muted">* Stored preference. Current worker evaluates on each run; digest timing needs the production scheduler.</small></div><div class="field full"><button class="btn" type="submit">Create alert</button></div></form>`);$('#alert-form').onsubmit=async e=>{e.preventDefault();try{await api('/alerts',{method:'POST',body:formData(e.target)});closeModal();toast('Alert created');navigate('alerts')}catch(err){toast(err.message,true)}}}
async function applications(){S.applications=await api('/applications');let stat={};for(const a of S.applications)stat[a.status]=(stat[a.status]||0)+1;$('#page').innerHTML=heading('APPLICATION MANAGER','Track your applications','Everything from first interest to final offer.',`<button class="btn" data-action="new-application">+ New application</button>`)+`<div class="stats"><div class="stat"><div class="stat-ico">▤</div><div><strong>${S.applications.length}</strong><small>Total tracked</small></div></div><div class="stat"><div class="stat-ico green">✓</div><div><strong>${stat.applied||0}</strong><small>Applied</small></div></div><div class="stat"><div class="stat-ico purple">♧</div><div><strong>${stat.interview||0}</strong><small>Interview</small></div></div><div class="stat"><div class="stat-ico orange">✦</div><div><strong>${stat.offer||0}</strong><small>Offers</small></div></div></div><div class="panel"><div class="panel-title"><h2>Application activity</h2><button class="text-btn" data-action="download-csv">Export CSV</button></div>${S.applications.length?S.applications.map(a=>`<div class="row-item"><div><strong>${esc(a.title)}</strong><p>${esc(a.company)} · Updated ${esc(date(a.updated_at))}</p>${a.notes?`<p>${esc(a.notes.slice(0,120))}</p>`:''}</div><div style="display:flex;align-items:center;gap:8px"><span class="pill ${esc(a.status)}">${esc(a.status)}</span><button class="btn btn-outline btn-small" data-action="edit-application" data-id="${esc(a.id)}">Edit</button></div></div>`).join(''):empty('▤','Nothing to track yet','Record applications manually or add one from any job detail page.',`<button class="btn" data-action="new-application">Add an application</button>`)}</div>`;refreshNav()}
function applicationForm(existing=null){const editing=Boolean(existing?.id);const a=existing||{company:'',title:'',status:'interested',applied_at:'',follow_up_at:'',notes:''};const options=['interested','applied','assessment','interview','followup','offer','rejected','withdrawn'];modal(`<h2>${editing?'Edit':'New'} application</h2><p>Track the stage and important details of your application.</p><form id="application-form" class="form-grid">${field('Company','company',a.company,'text','required')}${field('Job title','title',a.title,'text','required')}<div class="field"><label>Status</label><select name="status">${options.map(x=>`<option value="${x}" ${a.status===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('Applied date','applied_at',a.applied_at||'','date')}${field('Follow-up date','follow_up_at',a.follow_up_at||'','date')}${textfield('Private notes','notes',a.notes)}<div class="field full" style="display:flex;flex-direction:row;gap:9px;justify-content:flex-end">${editing?'<button type="button" class="btn btn-danger" id="application-delete">Delete</button>':''}<button class="btn" type="submit">${editing?'Save changes':'Track application'}</button></div></form>`);$('#application-form').onsubmit=async e=>{e.preventDefault();try{const body={...formData(e.target),job_id:a.job_id||null};for(const k of ['applied_at','follow_up_at'])body[k]=body[k]||null;await api(editing?'/applications/'+existing.id:'/applications',{method:editing?'PUT':'POST',body});closeModal();toast(editing?'Application updated':'Application saved');navigate('applications')}catch(err){toast(err.message,true)}};if(editing)$('#application-delete').onclick=async()=>{if(!confirm('Delete this application?'))return;try{await api('/applications/'+existing.id,{method:'DELETE'});closeModal();navigate('applications')}catch(e){toast(e.message,true)}}}
async function resume(){const docs=await api('/cv');$('#page').innerHTML=heading('CAREER DOCUMENTS','Resume center','Keep your CV files private and accessible.',`<button class="btn" data-action="profile">Edit CV details</button>`)+`<div class="columns"><div class="panel"><div class="panel-title"><h2>Uploaded resumes</h2></div><form id="cv-form" class="field"><label>Upload PDF, DOCX or TXT (max 3 MB)</label><input type="file" name="file" id="cv-file" accept=".pdf,.docx,.txt" required><button class="btn" style="justify-self:start;margin-top:9px" type="submit">Upload resume ↑</button></form>${docs.length?`<div style="margin-top:22px">${docs.map(d=>`<div class="row-item"><div><strong>${esc(d.filename)}</strong><p>${(d.bytes/1024).toFixed(0)} KB · ${esc(date(d.created_at))}</p></div><div style="display:flex;gap:6px"><button class="btn btn-outline btn-small" data-action="download-cv" data-id="${esc(d.id)}" data-name="${esc(d.filename)}">Download</button><button class="btn btn-outline btn-small" data-action="share-cv" data-id="${esc(d.id)}">Share link</button><button class="btn btn-outline btn-small" data-action="delete-cv" data-id="${esc(d.id)}">Delete</button></div></div>`).join('')}</div>`:''}</div><div class="panel"><div class="panel-title"><h2>Generate a simple resume</h2></div><p class="muted small" style="line-height:1.8">Generate a clean PDF from your confirmed profile information. This generator does not invent qualifications or experience.</p><button class="btn btn-outline" data-action="generate-resume">Generate profile PDF ↗</button><button class="btn btn-outline" data-action="tailored" style="margin-top:10px">My tailored CVs and cover letters</button><div class="infobar">Use a vacancy’s “Tailor CV + Letter” action to create editable, source-grounded versions. No AI provider is connected.</div></div></div>`;$('#cv-form').onsubmit=async e=>{e.preventDefault();const file=$('#cv-file').files[0];if(!file)return;const body=new FormData();body.append('file',file);try{await api('/cv/upload',{method:'POST',body});toast('Resume securely uploaded');resume()}catch(err){toast(err.message,true)}}}
async function profile(){S.profile=await api('/profile');const p=S.profile;$('#page').innerHTML=heading('YOUR CAREER','Professional profile','Keep your search preferences and CV information up to date.')+`<div class="panel"><div class="panel-title"><h2>About you</h2><span class="muted small">Private to your account</span></div><form id="profile-form"><div class="form-grid">${field('Full name','full_name',p.full_name)}${field('Professional headline','headline',p.headline)}${field('Country','country',p.country)}${field('Preferred city','city',p.city)}${field('Desired job titles (comma-separated)','desired_titles',p.desired_titles)}${field('Years of experience','years_experience',p.years_experience,'number','min="0" max="65"')}${field('Minimum salary expectation','salary_min',p.salary_min??'','number','min="0"')}${field('Currency','salary_currency',p.salary_currency)}${textfield('Skills (comma-separated)','skills',p.skills)}${textfield('Professional summary','summary',p.summary)}</div><div class="form-actions"><button class="btn" type="submit">Save my profile</button></div></form></div><div class="notice">CareerRadar uses your stated information for its rule-based job relevance estimate. It does not predict hiring outcomes.</div>`;$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const v=formData(e.target);v.years_experience=Number(v.years_experience||0);v.salary_min=v.salary_min?Number(v.salary_min):null;await api('/profile',{method:'PUT',body:v});S.profile=await api('/profile');toast('Profile saved');refreshNav()}catch(err){toast(err.message,true)}}}
async function notifications(){S.notifications=await api('/notifications');$('#page').innerHTML=heading('UPDATES','Notifications','Job matches delivered by the server-side matching worker.')+`<div class="panel">${S.notifications.length?S.notifications.map(n=>`<div class="row-item"><div><strong>${esc(n.title)}</strong><p>${esc(n.message)} · ${esc(date(n.created_at))}</p></div>${n.job_id?`<button class="btn btn-outline btn-small" data-action="notification-open" data-id="${esc(n.id)}" data-job="${esc(n.job_id)}">Open job</button>`:''}</div>`).join(''):empty('♧','You’re all caught up','Matching alerts will appear here when new vacancies are ingested and the background worker runs.')}</div>`;refreshNav()}
async function account(){$('#page').innerHTML=heading('ACCOUNT','Settings & privacy','Manage your session and personal information.')+`<div class="panel"><div class="row-item"><div><strong>Account email</strong><p>${esc(S.user.email)}</p></div><span class="pill">${esc(S.user.role)}</span></div><div class="row-item"><div><strong>Export personal account data</strong><p>Download a JSON copy of your profile, alerts and application records.</p></div><button class="btn btn-outline btn-small" data-action="export-account">Export</button></div><div class="row-item"><div><strong>Sign out</strong><p>Revoke this login session.</p></div><button class="btn btn-outline btn-small" data-action="logout">Sign out</button></div><div class="row-item"><div><strong>Delete account permanently</strong><p>Delete your profile, saved jobs, alerts, tracked applications and uploaded CV files.</p></div><button class="btn btn-danger btn-small" data-action="delete-account">Delete</button></div></div><div class="infobar">This self-hosted build has not completed independent security auditing or commercial privacy compliance review.</div>`}
async function admin(){if(S.user?.role!=='admin')throw Error('Admin access required');const data=await api('/admin/overview');$('#page').innerHTML=heading('CONTROL CENTER','Administration','Job ingestion and source monitoring.',`<button class="btn" data-action="sync-all">↻ Sync all sources</button>`)+`<div class="stats">${Object.entries(data.counts).slice(0,4).map(([name,count],i)=>`<div class="stat"><div class="stat-ico">${['♙','▤','♧','↗'][i]}</div><div><strong>${count}</strong><small>${esc(name)}</small></div></div>`).join('')}</div><div class="columns"><div class="panel"><div class="panel-title"><h2>Connect job source</h2></div><form id="provider-form" class="form-grid"><div class="field"><label>Provider type</label><select name="kind"><option value="greenhouse">Greenhouse</option><option value="lever">Lever</option></select></div>${field('Company board slug','slug','','text','required')}${field('Display name','display_name','','text','required')}<div class="field"><label>Permission</label><div class="small muted">Verify permitted use and redistribution before publishing listings.</div></div><div class="field full"><button class="btn" type="submit">Add source</button></div></form></div><div class="panel"><div class="panel-title"><h2>Add direct job listing</h2></div><form id="direct-form" class="form-grid">${field('Company','company','','text','required')}${field('Job title','title','','text','required')}${field('Location','location')}${field('Country','country','United Arab Emirates')}${field('Original HTTPS apply URL','url','','url','required')}${textfield('Job description','description')}<div class="field full"><button class="btn" type="submit">Publish direct listing</button></div></form></div></div><div class="panel"><div class="panel-title"><h2>Connected feeds</h2></div>${data.providers.length?data.providers.map(p=>`<div class="row-item"><div><strong>${esc(p.display_name)}</strong><p>${esc(p.id)} · ${p.enabled?'Enabled':'Disabled'}</p></div><button class="btn btn-outline btn-small" data-action="sync-provider" data-id="${esc(p.id)}">Sync now</button></div>`).join(''):empty('◎','No sources configured','Add an employer board above. Live feed ingestion only runs after an operator configures a source.')}</div><div class="panel"><div class="panel-title"><h2>Recent synchronization runs</h2></div>${data.runs.length?data.runs.map(r=>`<div class="row-item"><div><strong>${esc(r.provider_id)}</strong><p>${esc(date(r.started_at))} · New: ${r.new_count} · Updated: ${r.updated_count}${r.error?' · '+esc(r.error):''}</p></div><span class="pill">${esc(r.status)}</span></div>`).join(''):empty('◷','No ingestion runs yet','Synchronize a source to see the results here.')}</div>`;
 $('#provider-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/providers',{method:'POST',body:formData(e.target)});toast('Source configured');admin()}catch(err){toast(err.message,true)}};$('#direct-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/jobs',{method:'POST',body:formData(e.target)});toast('Job published');admin()}catch(err){toast(err.message,true)}}}
async function downloadProtected(url,filename){const response=await fetch('/api'+url,{headers:{Authorization:'Bearer '+S.token}});if(!response.ok)throw Error('Download failed');const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),5000)}

async function walkins(){const r=await api('/walkins');$('#page').innerHTML=heading('UAE INTERVIEW RADAR','Walk-in interviews','Moderator-reviewed future events with source links. Verify with the organiser before visiting.')+`<div class="panel">${r.items.length?r.items.map(e=>`<div class="row-item"><div><strong>${esc(e.title)} · ${esc(e.company)}</strong><p>📍 ${esc(e.venue)}, ${esc(e.city)} · ${esc(date(e.starts_at))}</p><p>Requirements: ${esc(e.requirements||'Not specified')} · Documents: ${esc(e.documents||'Check employer listing')}</p></div><a class="btn btn-outline btn-small" href="${esc(e.source_url)}" target="_blank" rel="noopener noreferrer">Original source ↗</a></div>`).join(''):empty('⌖','No reviewed walk-in interviews yet','An administrator can add events after checking their original announcement. No fictional interviews are shown as real.')}</div>${S.user?.role==='admin'?`<div class="panel"><h2>Add reviewed walk-in interview</h2><form id="walkin-form" class="form-grid">${field('Company','company','','text','required')}${field('Job title','title','','text','required')}${field('Venue','venue','','text','required')}${field('City','city','Dubai','text','required')}${field('Start (local)','starts_at','','datetime-local','required')}${field('End (local)','ends_at','','datetime-local','required')}${field('Original HTTPS URL','source_url','','url','required')}${textfield('Requirements','requirements')}${textfield('Documents to bring','documents')}<label><input name="moderator_reviewed" type="checkbox" value="true"> I reviewed the source and approve publication</label><button class="btn" type="submit">Add event</button></form></div>`:''}`;
if($('#walkin-form'))$('#walkin-form').onsubmit=async e=>{e.preventDefault();try{const v=formData(e.target);v.moderator_reviewed=Boolean(e.target.querySelector('[name="moderator_reviewed"]').checked);v.starts_at=new Date(v.starts_at).toISOString();v.ends_at=new Date(v.ends_at).toISOString();await api('/admin/walkins',{method:'POST',body:v});toast('Interview event saved');walkins()}catch(err){toast(err.message,true)}}}
async function comparePage(){const ids=S.compare.slice(0,4);let data=null;if(ids.length>=2){try{data=await api('/jobs/compare/batch?ids='+encodeURIComponent(ids.join(',')))}catch(e){toast(e.message,true)}}$('#page').innerHTML=heading('DECISION ASSISTANT','Compare job offers','Select up to four vacancies from the Discover page, then compare known details.',`<button class="btn btn-outline" data-action="compare-clear">Clear selection</button>`)+`<div class="panel"><p class="muted small">${ids.length}/4 vacancies selected. Unknown compensation and employer response information will never be estimated.</p>${data?`<div class="compare-grid">${data.items.map(j=>`<section class="compare-job"><h3>${esc(j.title)}</h3><p>${esc(j.company)}</p><dl><dt>Location</dt><dd>${esc(j.location||'Unknown')}</dd><dt>Salary</dt><dd>${j.salary_min?esc((j.currency||'')+' '+j.salary_min+' – '+(j.salary_max||'?')):'Not published'}</dd><dt>Work arrangement</dt><dd>${esc(j.work_type||'Unknown')}</dd><dt>Source freshness</dt><dd>${esc(j.trust.freshness.replaceAll('_',' '))}</dd></dl><button class="btn btn-outline btn-small" data-action="view-job" data-id="${esc(j.id)}">Details</button></section>`).join('')}</div>`:empty('⇄','Choose at least two jobs','Open Discover, click + Compare on two to four vacancies, then return here.',`<button class="btn" data-action="discover">Browse jobs</button>`)}</div>`}
async function insightsPage(){const data=await api('/reports/weekly?weeks=8');const counts=data.current_application_status_counts;$('#page').innerHTML=heading('MY PROGRESS','Weekly job-search report','Real statistics from your tracked activity, not estimates from external job sites.')+`<div class="stats"><div class="stat"><div><strong>${Object.values(counts).reduce((a,b)=>a+b,0)}</strong><small>Tracked applications</small></div></div><div class="stat"><div><strong>${counts.interview||0}</strong><small>Currently interviewing</small></div></div><div class="stat"><div><strong>${counts.offer||0}</strong><small>Current offers</small></div></div><div class="stat"><div><strong>${data.due_followups.length}</strong><small>Follow-ups due</small></div></div></div><div class="panel"><h2>Last 8 weeks</h2><div class="table-scroll"><table class="report-table"><thead><tr><th>Week starting</th><th>Applications added</th><th>Jobs saved</th><th>In-app alerts</th></tr></thead><tbody>${data.weeks.map(w=>`<tr><td>${esc(w.week_start)}</td><td>${w.applications_added}</td><td>${w.jobs_saved}</td><td>${w.alerts_received}</td></tr>`).join('')}</tbody></table></div><p class="muted small">${esc(data.notice)}</p></div><div class="panel"><h2>Follow-ups due</h2>${data.due_followups.length?data.due_followups.map(x=>`<div class="row-item"><span>Due: ${esc(date(x.follow_up_at))}</span><button class="btn btn-outline btn-small" data-action="applications">View tracker</button></div>`).join(''):empty('✓','No outstanding follow-ups','Add follow-up dates to applications to see them here.')}</div>`}
async function toolsPage(){const shares=await api('/cv/shares');const status=await api('/integrations/status');$('#page').innerHTML=heading('YOUR CAREER TOOLKIT','Career tools','Practical job-search tools with transparent integration status.')+`<div class="tool-grid"><div class="panel"><h2>✉ Email application review</h2><p>Paste a recruiter email and review its proposed status before updating your tracker.</p><button class="btn" data-action="mail-review">Review an email</button><p class="muted small">Inbox OAuth: ${esc(status.inbox_oauth)}. No automatic inbox reading.</p></div><div class="panel"><h2>♢ UAE offer warning check</h2><p>Scan a pasted offer for common warning terms. This is not official validation.</p><button class="btn" data-action="offer-check">Check offer text</button></div><div class="panel"><h2>⇄ Compare jobs</h2><p>Review salary, location and known employer information side by side.</p><button class="btn btn-outline" data-action="compare">Open comparisons (${S.compare.length})</button></div><div class="panel"><h2>⌖ Walk-in interviews</h2><p>Discover upcoming, moderator-reviewed interview events.</p><button class="btn btn-outline" data-action="walkins">View interview radar</button></div><div class="panel"><h2>▥ Job search insights</h2><p>Application counts, current statuses and upcoming follow-ups.</p><button class="btn btn-outline" data-action="insights">View weekly report</button></div><div class="panel"><h2>✎ Tailored CV and cover letters</h2><p>Create editable PDF/DOCX documents from a real job description and your saved CV.</p><button class="btn" data-action="tailored">My tailored documents</button></div><div class="panel"><h2>♡ Secure resume links</h2><p>Share an uploaded CV with expiry and revocation controls.</p><button class="btn btn-outline" data-action="resume">Manage CVs</button><p class="muted small">Each view consumes one allowed opening; not a verified human read.</p></div></div><div class="panel"><h2>Existing CV share links</h2>${shares.length?shares.map(s=>`<div class="row-item"><div><strong>${esc(s.filename)}</strong><p>Expires ${esc(date(s.expires_at))} · Opened ${s.open_count}/${s.max_opens} · ${s.revoked_at?'Revoked':'Active or expired depending on date'}</p></div>${!s.revoked_at?`<button class="btn btn-outline btn-small" data-action="revoke-cv" data-id="${esc(s.id)}">Revoke</button>`:''}</div>`).join(''):empty('▣','No shared CVs','Open Resume center, upload a CV, then choose Share link.')}</div><div class="notice">WhatsApp sharing is user-initiated; automated messaging and live commute-time filtering require separate provider integrations.</div>`}
async function tailorJob(jobId){
 if(!S.user)return auth('login');
 const [job,docs,featureFlags]=await Promise.all([api('/jobs/'+encodeURIComponent(jobId)),api('/cv'),api('/features')]);
 modal(`<h2>Tailor your CV and cover letter</h2><p>For <strong>${esc(job.title)}</strong> at ${esc(job.company)}. The draft uses only information from your saved profile and selected resume. Review every statement before applying.</p><form id="tailor-form" class="field"><label for="tailor-cv">Select the original CV</label><select id="tailor-cv" class="share-input"><option value="">Use my saved profile only</option>${docs.map(d=>`<option value="${esc(d.id)}">${esc(d.filename)}</option>`).join('')}</select><label for="tailor-kind">Create</label><select id="tailor-kind" class="share-input"><option value="both">CV and cover letter</option><option value="cv">Tailored CV</option><option value="cover_letter">Cover letter</option></select><label for="tailor-tone">Writing style</label><select id="tailor-tone" class="share-input"><option value="professional">Professional</option><option value="concise">Concise</option><option value="formal">Formal</option></select><label for="tailor-mode">Generation method</label><select id="tailor-mode" class="share-input"><option value="local">Private matching (free, no external AI)</option>${featureFlags.ai_cv_tailoring?'<option value="ai">AI-enhanced rewrite (shares data with external AI)</option>':''}</select><label class="consent-check"><input id="tailor-consent" type="checkbox"/> I explicitly agree to send the selected CV, profile and vacancy to the configured AI provider when AI mode is selected.</label><div class="notice">Matching is based on terms in the job description that also appear in your CV/profile. It does not invent experience or send an application. PDF and DOCX exports are available after editing.</div><button class="btn" type="submit" id="tailor-submit">Create editable drafts</button></form><p class="muted small">No uploaded CV? <button class="text-btn" data-action="close-modal">Close and open Resume center to upload one.</button></p>`);
 $('#tailor-form').onsubmit=async e=>{e.preventDefault();const btn=$('#tailor-submit');btn.disabled=true;btn.textContent='Generating...';try{const payload={kind:$('#tailor-kind').value,tone:$('#tailor-tone').value,cv_id:$('#tailor-cv').value||null,mode:$('#tailor-mode').value,allow_external_processing:$('#tailor-consent').checked};const r=await api('/jobs/'+encodeURIComponent(jobId)+'/tailor',{method:'POST',body:payload});toast(r.documents.length+' draft(s) created');closeModal();await tailoredPage();await editTailored(r.documents[0].id)}catch(err){toast(err.message,true);btn.disabled=false;btn.textContent='Create editable drafts'}};
}
async function tailoredPage(){
 const docs=await api('/tailored');S.route='tailored';refreshNav();$('#page').innerHTML=heading('YOUR PERSONAL DOCUMENT LIBRARY','Tailored CVs & cover letters','Create a separate version for every vacancy, edit your wording and export as PDF or Word.',`<button class="btn btn-outline" data-action="discover">Browse jobs</button>`)+`<div class="notice">To create a draft, open a job listing and click <strong>Tailor CV + Letter</strong>. For best results, first upload your original CV in Resume center.</div><div class="panel" style="margin-top:15px"><div class="panel-title"><h2>My job-specific drafts</h2><span class="muted small">${docs.length} documents</span></div>${docs.length?docs.map(d=>`<div class="row-item"><div><strong>${esc(d.title)}</strong><p>${esc(d.kind==='cv'?'CV':'Cover letter')} · ${esc(d.company)} · Last edited ${esc(date(d.updated_at))}</p></div><div class="draft-actions"><button class="btn btn-small" data-action="edit-tailored" data-id="${esc(d.id)}">Edit</button><button class="btn btn-outline btn-small" data-action="export-tailored" data-format="pdf" data-id="${esc(d.id)}">PDF</button><button class="btn btn-outline btn-small" data-action="export-tailored" data-format="docx" data-id="${esc(d.id)}">Word</button><button class="btn btn-outline btn-small" data-action="delete-tailored" data-id="${esc(d.id)}">Delete</button></div></div>`).join(''):empty('✎','No tailored documents yet','Open a job to generate matching drafts using your uploaded CV and saved profile.',`<button class="btn" data-action="discover">Find a job</button>`)}</div>`;
}
async function editTailored(id){const d=await api('/tailored/'+encodeURIComponent(id));modal(`<h2>Review ${esc(d.kind==='cv'?'tailored CV':'cover letter')}</h2><p>This draft belongs to you. Make sure all claims are accurate; no application is sent automatically.</p><form id="draft-edit" class="field">${field('Document title','title',d.title,'text','required maxlength="180"')}<div class="field"><label for="draft-content">Editable document</label><textarea id="draft-content" class="kit-textarea" minlength="15" maxlength="40000" required>${esc(d.content)}</textarea></div><p class="muted small">Matched job/CV skills: ${esc(d.matched_skills.join(', ')||'None explicitly matched')}. This is an evidence-based draft, not an AI-verified credential assessment.</p><button class="btn" type="submit">Save edits</button></form><div class="draft-actions" style="margin-top:12px"><button class="btn btn-outline" id="draft-pdf">Download PDF</button><button class="btn btn-outline" id="draft-docx">Download Word</button></div>`);
 const save=async()=>{const title=$('#f-title').value,content=$('#draft-content').value;return api('/tailored/'+id,{method:'PUT',body:{title,content}})};
 $('#draft-edit').onsubmit=async e=>{e.preventDefault();try{await save();toast('Saved');closeModal();tailoredPage()}catch(err){toast(err.message,true)}};
 for(const format of ['pdf','docx'])$('#draft-'+format).onclick=async()=>{try{await save();await downloadProtected('/tailored/'+id+'/export.'+format,'career-'+d.kind+'-'+id.slice(0,8)+'.'+format);toast('Saved and exported')}catch(err){toast(err.message,true)}};
}
async function applicationKit(id){const d=await api('/jobs/'+id+'/application-kit');modal(`<h2>Application kit: ${esc(d.title)}</h2><p>No application is sent automatically. Review and personalize the draft before using it.</p><textarea class="kit-textarea" readonly>${esc(d.cover_letter_draft)}</textarea><p class="muted small">Matched skills: ${esc(d.matching_declared_skills.join(', ')||'None recorded')}</p><button class="btn" id="copy-kit">Copy draft</button>`);$('#copy-kit').onclick=()=>navigator.clipboard.writeText(d.cover_letter_draft).then(()=>toast('Draft copied')).catch(()=>toast('Select text to copy',true))}
async function roadmapModal(id){const d=await api('/jobs/'+id+'/roadmap');modal(`<h2>Skill growth plan</h2><p>Suggestions are based on explicitly mentioned terms and your declared profile. Not a verified list of employer requirements.</p>${d.steps.length?d.steps.map(x=>`<div class="row-item"><div><strong>${esc(x.skill)}</strong><p>${esc(x.next_step)}</p></div></div>`).join(''):'No recognized skill gaps detected from the limited keyword list.'}`)}
async function whatsappModal(id){const d=await api('/integrations/whatsapp/preview',{method:'POST',body:{job_id:id}});modal(`<h2>Share via WhatsApp</h2><p>Opens WhatsApp with a prepared message. You must choose the recipient and press Send yourself.</p><a class="btn" href="${esc(d.url)}" rel="noopener noreferrer" target="_blank">Open WhatsApp ↗</a>`)}
async function directionsModal(id){const origin=prompt('Your starting city or address (used only to open Google Maps):',S.profile?.city||'Dubai');if(!origin)return;const d=await api('/commute/directions?'+new URLSearchParams({origin,job_id:id,mode:'driving'}));modal(`<h2>Commute and directions</h2><p>${esc(d.note)}</p><a class="btn" href="${esc(d.url)}" rel="noopener noreferrer" target="_blank">Open route in Google Maps ↗</a>`)}
async function shareCv(id){const d=await api('/cv/shares',{method:'POST',body:{cv_id:id,expires_days:7,max_opens:10}});const link=location.origin+d.path;modal(`<h2>Private CV share link created</h2><p>Expires ${esc(date(d.expires_at))}, or after 10 openings. Anyone possessing the link may open your CV.</p><input id="cv-share-url" class="share-input" value="${esc(link)}" readonly><button class="btn" id="copy-cv-link">Copy secure link</button><p class="muted small">Revoke links under Career tools.</p>`);$('#copy-cv-link').onclick=()=>navigator.clipboard.writeText(link).then(()=>toast('Link copied')).catch(()=>toast('Select link to copy',true))}
function mailReview(){modal(`<h2>Review an application email</h2><p>Paste a confirmation, interview invitation, offer or rejection email. This text is analyzed locally on the server and not saved.</p><form id="mail-form" class="field">${field('From','sender')}${field('Subject','subject')}${textfield('Email text','body', '',5)}<button class="btn" type="submit">Classify email</button></form><div id="mail-result"></div>`);$('#mail-form').onsubmit=async e=>{e.preventDefault();try{const v=formData(e.target);const r=await api('/email/preview',{method:'POST',body:v});let apps=await api('/applications');$('#mail-result').innerHTML=`<div class="notice">Suggested status: <strong>${esc(r.suggested_status)}</strong>. ${esc(r.warning)}</div>${r.suggested_status==='unknown'?'<p>No clear status found. Update the tracker manually.</p>':`<label>Choose application to update</label><select id="mail-application" class="share-input">${apps.map(a=>`<option value="${esc(a.id)}">${esc(a.company)} — ${esc(a.title)}</option>`).join('')}</select><button class="btn" id="apply-email" ${apps.length?'':'disabled'}>Confirm change</button>`}`;if($('#apply-email'))$('#apply-email').onclick=async()=>{await api('/email/confirm',{method:'POST',body:{...v,application_id:$('#mail-application').value,status:r.suggested_status}});toast('Application updated');closeModal()}}catch(err){toast(err.message,true)}}}
function offerCheck(){modal(`<h2>UAE offer warning check</h2><p>Paste offer text to look for basic warning terms. CareerRadar cannot verify the offer's authenticity.</p><form id="offer-form" class="field">${textfield('Offer wording','text','',6)}<button class="btn" type="submit">Check warning signs</button></form><div id="offer-result"></div><a href="https://www.mohre.gov.ae/" target="_blank" rel="noopener noreferrer">Official MOHRE website ↗</a>`);$('#offer-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/offers/check',{method:'POST',body:formData(e.target)});$('#offer-result').innerHTML=`<div class="notice"><strong>${d.warning_signs.length?d.warning_signs.length+' warning sign(s)':'No configured warning terms matched'}</strong><p>${esc(d.warning_signs.join('; ')||'This does not mean the offer is genuine.')}</p><p>${esc(d.note)}</p></div>`}catch(err){toast(err.message,true)}}}

async function act(action,el){try{if(NAV.some(n=>n[0]===action)||['account','admin','discover','notifications'].includes(action))return navigate(action);if(action==='login'||action==='register')return auth(action);if(action==='close-modal')return closeModal();if(action==='search')return performSearch();if(action==='clear-search'){S.q='';S.location='';S.page=1;return discover()}if(action==='prev-page'||action==='next-page'){S.page+=(action==='next-page'?1:-1);return discover()}if(action==='view-job')return navigate('job',el.dataset.id);if(action==='compare-toggle'){const id=el.dataset.id;const already=S.compare.includes(id);if(!already&&S.compare.length===4){toast('Maximum 4 jobs can be compared');return}S.compare=already?S.compare.filter(x=>x!==id):[...S.compare,id];localStorage.setItem('cr_compare',JSON.stringify(S.compare));return navigate(S.route==='job'?'job':S.route,S.route==='job'?id:null)}if(action==='compare-clear'){S.compare=[];localStorage.setItem('cr_compare','[]');return comparePage()};if(action==='new-alert')return newAlert();if(action==='new-application')return applicationForm();if(action==='edit-application')return applicationForm(S.applications.find(a=>a.id===el.dataset.id));if(action==='delete-alert'){if(!confirm('Delete this job alert?'))return;await api('/alerts/'+el.dataset.id,{method:'DELETE'});return navigate('alerts')}
 if(action==='toggle-save'){if(!S.user)return auth('login');const id=el.dataset.id;const found=S.saved.some(x=>x.id===id);await api('/saved/'+id,{method:found?'DELETE':'POST'});S.saved=await api('/saved');toast(found?'Removed from saved jobs':'Saved job');return S.route==='job'?jobDetails(id):navigate(S.route)}
 if(action==='track-job'){if(!S.user)return auth('login');let j=await api('/jobs/'+el.dataset.id);return applicationForm({job_id:j.id,company:j.company,title:j.title,status:'interested',notes:''})}
 if(action==='match-job'){if(!S.user)return auth('login');const r=await api('/match/'+el.dataset.id);return modal(`<h2>Job relevance estimate: ${r.score}/100</h2><p>${esc(r.explanation)}</p><div class="setup-card"><strong>Matching skills:</strong> ${esc(r.skills_matched.join(', ')||'None identified from your saved profile.')}<br><strong>Title aligned:</strong> ${r.title_match?'Yes':'Not detected'}<br><strong>City aligned:</strong> ${r.location_match?'Yes':'Not detected'}</div>`)}
 if(action==='report-job'){if(!S.user)return auth('login');let why=prompt('What appears wrong with this listing? (minimum 8 characters)');if(!why)return;await api('/jobs/'+el.dataset.id+'/report',{method:'POST',body:{reason:why}});return toast('Report received')}
 if(action==='notification-open'){await api('/notifications/'+el.dataset.id+'/read',{method:'POST'});return navigate('job',el.dataset.job)}
 if(action==='sync-provider'){toast('Connecting to the source…');await api('/admin/sync/'+encodeURIComponent(el.dataset.id),{method:'POST'});toast('Source synchronized');return admin()}
 if(action==='sync-all'){const d=await api('/admin/overview');for(const provider of d.providers){try{await api('/admin/sync/'+encodeURIComponent(provider.id),{method:'POST'})}catch(e){toast(e.message,true)}}return admin()}
 if(action==='application-kit')return applicationKit(el.dataset.id);if(action==='tailor-job')return tailorJob(el.dataset.id);if(action==='edit-tailored')return editTailored(el.dataset.id);if(action==='delete-tailored'){if(!confirm('Delete this draft?'))return;await api('/tailored/'+el.dataset.id,{method:'DELETE'});toast('Draft deleted');return tailoredPage()}if(action==='export-tailored'){return downloadProtected('/tailored/'+el.dataset.id+'/export.'+el.dataset.format,'career-'+el.dataset.id.slice(0,8)+'.'+el.dataset.format)}if(action==='roadmap')return roadmapModal(el.dataset.id);if(action==='share-whatsapp')return whatsappModal(el.dataset.id);if(action==='directions')return directionsModal(el.dataset.id);if(action==='share-cv')return shareCv(el.dataset.id);if(action==='revoke-cv'){await api('/cv/shares/'+el.dataset.id,{method:'DELETE'});toast('Link revoked');return toolsPage()}if(action==='mail-review')return mailReview();if(action==='offer-check')return offerCheck();if(action==='delete-cv'){if(!confirm('Delete this resume file?'))return;await api('/cv/'+el.dataset.id,{method:'DELETE'});toast('Resume deleted');return resume()}
 if(action==='download-cv')return await downloadProtected('/cv/'+el.dataset.id+'/download',el.dataset.name||'resume');if(action==='generate-resume')return await downloadProtected('/cv/resume/generate.pdf','careerradar-resume.pdf');if(action==='download-csv')return await downloadProtected('/applications/export.csv','applications.csv');
 if(action==='export-account'){const data=await api('/account/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='careerradar-account-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);return}
 if(action==='logout'){await api('/auth/logout',{method:'POST'});S.token='';S.user=null;sessionStorage.removeItem('cr_token');S.saved=[];S.alerts=[];S.applications=[];toast('Signed out');return navigate('discover')}
 if(action==='delete-account'){if(!confirm('Permanently delete your account and all data? This cannot be undone.'))return;await api('/auth/account',{method:'DELETE'});S.token='';S.user=null;sessionStorage.removeItem('cr_token');toast('Account removed');return navigate('discover')}
 }catch(err){toast(err.message,true)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();act(el.dataset.action,el)}});
async function start(){document.querySelector('#today').textContent=new Date().toLocaleDateString('en-AE',{day:'numeric',month:'short',year:'numeric'});try{await api('/health');$('#backend-state').textContent='Online'}catch{$('#backend-state').textContent='Offline'}await loadUser();const first=location.hash.replace('#','');navigate(first&&NAV.some(x=>x[0]===first)?first:'discover');if('serviceWorker' in navigator)navigator.serviceWorker.register('/service-worker.js').catch(()=>{});
}
start();
